// Purpose: ROW-020 and ROW-022 (REQ-010) — on the checker page, in every browser of the harness,
// opening a highlighted word by click (tap on a phone) or by Enter shows at most 5 suggestions and an
// Ignore choice; a flagged word with no suggestion shows "Sin sugerencias" beside Ignore, never an
// empty list.
// Provenance: generated by tests/invariants/suggestions-population.ts from dictionary-es 4.0.0 (the
// SHA-256-pinned oracle, D-029) and by fresh random consonant strings, with a fresh seed per run;
// positions are the test's own record of where it placed each word.
//
// Test argument
// ROW-020 promise: click or Enter on a highlighted word opens a list of at most 5 suggestions with an
//   Ignore choice (REQ-010 fail-if "the list holds more than 5 suggestions … Ignore is missing";
//   A-005 "clicking one shows up to 5 suggestions … or Ignore"; A-015 keyboard).
// ROW-020 wrong product: a menu that lists every suggestion the engine returns (8 for "galaa"), or
//   one that opens on click only (a span with a click handler, no key handler), or a list without
//   Ignore.
// ROW-020 given: one check of a text holding 2 generated misspellings with at least 6 dictionary
//   words one edit away (more than 5 suggestions plausibly exist) and 1 generated accent error; when:
//   each highlight is opened by pointer, closed with Escape, then reached by Tab and opened with
//   Enter; then: each opening shows a menu of 1 to 5 suggestions and an Ignore choice — and no menu
//   was open before the first press.
// ROW-020 controls: opening one highlight by pointer shows a menu holding at least one suggestion —
//   the flags, the menu and its reading work; untouched by a list longer than 5, a missing Ignore or
//   a dead Enter key.
// ROW-020 technique: a generated sample salted with crowded misspellings so the 5-cap is reached
//   every run, each word opened both ways; per browser and on the phone (RULE-014, REQ-042).
// cases: ROW-020 target=ROW-020-click-or-enter-on-a-highlighted-word-shows-at-most-5-suggestions-and-ignore control=ROW-020-control-a-highlighted-word-opens-a-menu-with-suggestions
//
// ROW-022 promise: a flagged word with no suggestion shows "Sin sugerencias" beside Ignore, never an
//   empty list (REQ-010 fail-if "a word with no suggestion shows an empty list without 'Sin
//   sugerencias'"; A-018 the literal "Sin sugerencias").
// ROW-022 wrong product: a menu that renders the empty suggestion array as an empty box with only
//   Ignore, or that does not open at all for a word with no suggestion.
// ROW-022 given: one check of a text holding a fresh 12-consonant string (no dictionary word lies
//   within two edits of a 12-letter word without a vowel) and, as the near miss, a generated accent
//   error that has a correction; when: each highlight's menu is opened; then: the consonant string's
//   menu shows no suggestion, the note "Sin sugerencias" and Ignore; the near miss's menu shows
//   suggestions and no "Sin sugerencias".
// ROW-022 controls: the consonant string is highlighted and its menu opens with Ignore — the case is
//   reached; untouched by a missing note.
// ROW-022 technique: a decoy beside the target (a word with suggestions must not say "Sin
//   sugerencias"), fresh strings per run.
// cases: ROW-022 target=ROW-022-a-flagged-word-with-no-suggestion-shows-sin-sugerencias-beside-ignore control=ROW-022-control-the-word-with-no-suggestion-is-highlighted-and-its-menu-opens

import { expect, test, type Page } from '@playwright/test';
import { asActor, compose, enterOffer, freshRandom, openChecker, pressCheck, readHighlights, type Placed, type Rng } from './harness';
import { flagsAt, openMenu, openMenuByEnter, openMenuByPointer, readMenu, sprinkle } from './suggestions-helpers';
import { crowdedErrors, uniqueCorrectionErrors } from './suggestions-population';

const WAIT_MS = 15_000;

async function checked(page: Page, rng: Rng, words: string[], row: string): Promise<{ text: string; at: Placed[] }> {
  const { text, placed } = compose(sprinkle(rng, words));
  const at = placed.filter((p) => words.includes(p.word));
  if (at.length !== words.length) throw new Error(`setup: ${at.length} of ${words.length} anchors placed once each`);
  await openChecker(page);
  await enterOffer(page, text);
  expect((await readMenu(page)).open, `${row}: no menu is open before the check`).toBe(false);
  expect((await pressCheck(page)).status, `${row}: the page's check is answered`).toBe(200);
  await expect
    .poll(async () => (await flagsAt(page, text)).map((f) => f.start).filter((s) => at.some((p) => p.start === s)).length, {
      message: `${row}: each placed misspelling is highlighted at its place in ${JSON.stringify(text)} (seed ${rng.seed})`,
      timeout: WAIT_MS,
    })
    .toBe(at.length);
  return { text, at };
}

async function closeWithEscape(page: Page, row: string): Promise<void> {
  await page.keyboard.press('Escape');
  await expect(openMenu(page), `${row}: Escape closes the menu before the next word is opened`).toHaveCount(0, { timeout: WAIT_MS });
}

const nonWord = (rng: Rng) => {
  const consonants = 'bcdfghjklmnpqrstvz';
  let w = '';
  for (let i = 0; i < 12; i++) w += consonants[rng.int(consonants.length)];
  return w;
};

test('ROW-020-click-or-enter-on-a-highlighted-word-shows-at-most-5-suggestions-and-ignore', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const words = [...crowdedErrors(rng, 2), ...uniqueCorrectionErrors(rng, 1, ['accent'])].map((m) => m.wrong);
  const { text, at } = await checked(page, rng, words, 'ROW-020');

  const seen: string[] = [];
  for (const p of at) {
    await openMenuByPointer(page, text, p.start, 'ROW-020');
    const byPointer = await readMenu(page);
    seen.push(`${p.word} by pointer: ${JSON.stringify(byPointer)}`);
    expect(byPointer.suggestions.length, `ROW-020: "${p.word}" opened by pointer shows 1 to 5 suggestions — ${seen.at(-1)}`).toBeGreaterThanOrEqual(1);
    expect(byPointer.suggestions.length, `ROW-020: "${p.word}" opened by pointer shows at most 5 suggestions — ${seen.at(-1)}`).toBeLessThanOrEqual(5);
    expect(byPointer.ignore, `ROW-020: "${p.word}" opened by pointer shows an Ignore choice`).toBeGreaterThan(0);
    await closeWithEscape(page, 'ROW-020');

    await openMenuByEnter(page, text, p.start, 'ROW-020');
    const byEnter = await readMenu(page);
    seen.push(`${p.word} by Enter: ${JSON.stringify(byEnter)}`);
    expect(byEnter.suggestions.length, `ROW-020: "${p.word}" opened by Enter shows 1 to 5 suggestions — ${seen.at(-1)}`).toBeGreaterThanOrEqual(1);
    expect(byEnter.suggestions.length, `ROW-020: "${p.word}" opened by Enter shows at most 5 suggestions — ${seen.at(-1)}`).toBeLessThanOrEqual(5);
    expect(byEnter.ignore, `ROW-020: "${p.word}" opened by Enter shows an Ignore choice`).toBeGreaterThan(0);
    await closeWithEscape(page, 'ROW-020');
  }
});

test('ROW-020-control-a-highlighted-word-opens-a-menu-with-suggestions', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const words = uniqueCorrectionErrors(rng, 1).map((m) => m.wrong);
  const { text, at } = await checked(page, rng, words, 'ROW-020 control');
  await openMenuByPointer(page, text, at[0].start, 'ROW-020 control');
  const menu = await readMenu(page);
  expect(menu.suggestions.length, `ROW-020 control: "${at[0].word}"'s menu holds a suggestion — ${JSON.stringify(menu)}`).toBeGreaterThan(0);
});

test('ROW-022-a-flagged-word-with-no-suggestion-shows-sin-sugerencias-beside-ignore', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const none = nonWord(rng);
  const near = uniqueCorrectionErrors(rng, 1, ['accent'])[0].wrong;
  const { text, at } = await checked(page, rng, rng.shuffle([none, near]), 'ROW-022');
  const pNone = at.find((p) => p.word === none)!;
  const pNear = at.find((p) => p.word === near)!;

  await openMenuByPointer(page, text, pNone.start, 'ROW-022');
  const empty = await readMenu(page);
  expect(empty.suggestions, `ROW-022: "${none}" has no suggestion to show — ${JSON.stringify(empty)}`).toEqual([]);
  expect(empty.noSuggestions ?? '(no data-element="no-suggestions" shown)', `ROW-022: "${none}"'s menu says "Sin sugerencias"`).toMatch(/^Sin sugerencias\.?$/);
  expect(empty.ignore, `ROW-022: "Sin sugerencias" stands beside Ignore`).toBeGreaterThan(0);
  await page.keyboard.press('Escape');
  await expect(openMenu(page), 'ROW-022: Escape closes the menu before the next word is opened').toHaveCount(0, { timeout: WAIT_MS });

  await openMenuByPointer(page, text, pNear.start, 'ROW-022');
  const full = await readMenu(page);
  expect(full.suggestions.length, `ROW-022 near miss: "${near}" shows its suggestions — ${JSON.stringify(full)}`).toBeGreaterThan(0);
  expect(full.noSuggestions, `ROW-022 near miss: a word with suggestions does not say "Sin sugerencias"`).toBeNull();
});

test('ROW-022-control-the-word-with-no-suggestion-is-highlighted-and-its-menu-opens', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const none = nonWord(rng);
  const { text, at } = await checked(page, rng, [none], 'ROW-022 control');
  expect((await readHighlights(page, text)).map((h) => h.word), 'ROW-022 control: only the consonant string is highlighted').toEqual([none]);
  await openMenuByPointer(page, text, at[0].start, 'ROW-022 control');
  expect((await readMenu(page)).ignore, `ROW-022 control: "${none}"'s menu opens with Ignore`).toBeGreaterThan(0);
});
